<?php
declare(strict_types=1);require_once __DIR__.'/auth.php';$user=require_role('operario','supervisor');
$carros=db()->query('SELECT id,codigo,descripcion FROM carros WHERE activo=1 ORDER BY codigo')->fetchAll();$codigo=trim((string)($_GET['carro']??''));$carro=null;$historial=[];$error='';
if($codigo!==''){$stmt=db()->prepare('SELECT id,codigo,descripcion,ubicacion FROM carros WHERE codigo=? AND activo=1 LIMIT 1');$stmt->execute([$codigo]);$carro=$stmt->fetch();if(!$carro)$error='El carro seleccionado no existe o está inactivo.';else{$stmt=db()->prepare('SELECT m.id,m.tipo,m.descripcion AS trabajo,m.foto,m.realizada_en,u.nombre AS trabajador FROM mantenciones m INNER JOIN usuarios u ON u.id=m.usuario_id WHERE m.carro_id=? ORDER BY m.realizada_en DESC,m.id DESC');$stmt->execute([(int)$carro['id']]);$historial=$stmt->fetchAll();}}
require_once __DIR__.'/partials/layout.php';layout_start('Historial de mantenciones',$user,'historial');
?><a class="module-back" href="panel.php">← Volver al escritorio</a><section class="module-card"><h1>Historial de mantenciones</h1><p>Selecciona un carro para consultar todas sus mantenciones registradas.</p><form method="get"><label for="carro">Carro</label><select id="carro" name="carro" required><option value="">Selecciona un carro</option><?php foreach($carros as $item): ?><option value="<?=e($item['codigo'])?>" <?=$codigo===$item['codigo']?'selected':''?>><?=e($item['codigo'])?><?= $item['descripcion']?' — '.e($item['descripcion']):''?></option><?php endforeach;?></select><button type="submit">Abrir historial</button></form><?php if($error): ?><div class="module-alert error" role="alert"><?=e($error)?></div><?php endif;?></section><?php if($carro): ?><section class="module-card"><h2><?=e($carro['codigo'])?></h2><p><?=e($carro['descripcion']??'')?><?= $carro['ubicacion']?' · '.e($carro['ubicacion']):''?> · <?=count($historial)?> mantención(es)</p><?php if(!$historial): ?><div class="module-alert warn">No hay mantenciones registradas para este carro.</div><?php else: ?><div class="module-list"><?php foreach($historial as $registro): ?><article class="history-item"><h3><?=e($registro['tipo'])?></h3><div class="history-meta"><?=e(date('d/m/Y H:i',strtotime($registro['realizada_en'])))?> · Registrada por <?=e($registro['trabajador'])?></div><p><?=nl2br(e($registro['trabajo']))?></p><?php if($registro['foto']): ?><img class="history-photo" src="uploads/<?=e($registro['foto'])?>" alt="Foto de la mantención" loading="lazy"><?php endif;?><?php if($user['rol']==='supervisor'): ?><div class="module-actions"><a href="editar_mantencion.php?id=<?=$registro['id']?>">Editar</a><form method="post" action="eliminar_mantencion.php" onsubmit="return confirm('¿Eliminar esta mantención?');"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$registro['id']?>"><button class="danger" type="submit">Eliminar</button></form></div><?php endif;?></article><?php endforeach;?></div><?php endif;?></section><?php endif;?><?php layout_end();
